<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Accessor\TenantMarkForDeleteTimeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantMarkForDeleteTimeAccessor trait.
 *
 * Covers null default, string/VO assignment via withMarkForDeleteTime,
 * getMarkForDeleteTime/markForDeleteTime accessors, and isMarkForDeleteTimeChanged with/without original.
 */
class TenantMarkForDeleteTimeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMarkForDeleteTime creates a new instance with the MarkForDeleteTime set
     * from a string value, and getMarkForDeleteTime returns the primitive string.
     */
    public function testWithMarkForDeleteTimeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteTimeAccessorUnitTest();

        // Act
        $result = $holder->withMarkForDeleteTime((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getMarkForDeleteTime());
    }
    /**
     * Asserts that withmarkForDeleteTime has access to the value object
     * from a string value, and getMarkForDeleteTime returns the primitive string.
     */
    public function testWithMarkForDeleteTimeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteTimeAccessorUnitTest();

        // Act
        $result = $holder->withMarkForDeleteTime((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->markForDeleteTime()->value());
    }
    public function testChangedMarkForDeleteTime(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteTimeAccessorUnitTest();
        $original = $holder->withMarkForDeleteTime((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withMarkForDeleteTime((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withMarkForDeleteTime((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isMarkForDeleteTimeChanged();
        $withSame = $original->isMarkForDeleteTimeChanged($same);
        $withDiferent = $original->isMarkForDeleteTimeChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantMarkForDeleteTimeAccessorUnitTest
{
    use TenantMarkForDeleteTimeAccessor;
}
